test("docs page emits no console errors", async ({ page }) => {
  const consoleErrors: string[] = [];
  const pageErrors: string[] = [];
  const failedRequests: Array<{url: string, status?: number}> = [];

  // Set up error listeners BEFORE navigation
  page.on("console", (msg) => {
    if (msg.type() === "error") {
      consoleErrors.push(msg.text());
    }
  });

  page.on("pageerror", (err) => {
    pageErrors.push(err.message);
  });

  // Capture failed requests with their URLs
  page.on("response", (response) => {
    if (response.status() === 404) {
      failedRequests.push({
        url: response.url(),
        status: response.status()
      });
    }
  });

  page.on("requestfailed", (request) => {
    const url = request.url();
    const failure = request.failure()?.errorText;
    failedRequests.push({
      url: url,
      status: undefined // requestfailed doesn't have status
    });
  });

  // Navigate to docs page
  await page.goto("/docs");
  // Use domcontentloaded instead of networkidle since page may have ongoing requests
  await page.waitForLoadState("domcontentloaded");

  // Wait for any async operations to complete
  await page.waitForTimeout(5000);

  // Filter out known harmless errors (same pattern as other console error tests)
  // Note: "Failed to load resource" with 404s are real errors that need fixing
  const realErrors = consoleErrors.filter(err => 
    !err.includes("React DevTools") &&
    !err.includes("defaultProps") &&
    !err.includes("Warning:") &&
    !err.includes("[HMR]") &&
    !err.includes("Download the React DevTools") &&
    !err.includes("Quirks Mode") // Browser warning, not a real error
    // DO NOT filter out "Failed to load resource" - these are real 404 errors
  );

  // Assert no real console errors
  if (realErrors.length > 0 || failedRequests.length > 0) {
    console.log("Failed request URLs:", failedRequests.map(r => r.url).join(", "));
    console.log("All console errors:", consoleErrors);
  }
  expect(realErrors, `Expected no console errors, but found ${realErrors.length} error(s): ${realErrors.join("; ")}. Failed request URLs: ${failedRequests.map(r => r.url).join(", ")}`).toHaveLength(0);
  expect(pageErrors, `Expected no page errors, but found ${pageErrors.length} error(s): ${pageErrors.join("; ")}`).toHaveLength(0);
});

