// Update URL when filters change (but avoid redirect loop)
useEffect(() => {
  // Skip if we're still initializing from URL params or if manifest hasn't loaded
  if (loading || !manifest) return;

  const params = new URLSearchParams();

  if (selectedType !== "all") params.set("type", selectedType);
  // Only include status in URL if it differs from default "active" OR if URL already has it
  // This prevents redirect loops when defaulting to "active"
  const urlStatus = searchParams.get("status");
  if (selectedStatus !== "all") {
    // Only add status param if it's not "active" OR if URL already has "active"
    if (selectedStatus !== "active" || urlStatus === "active") {
      params.set("status", selectedStatus);
    }
  }
  if (searchQuery.trim() !== "") params.set("search", searchQuery.trim());

  Object.entries(selectedTags).forEach(([category, value]) => {
    if (value !== "all") {
      params.set(`tag:${category}`, value);
    }
  });

  const currentParams = new URLSearchParams(searchParams.toString());
  // Sort keys to ensure consistent comparison
  currentParams.sort();
  params.sort();

  // Only update URL if params actually changed (avoid infinite loops)
  if (currentParams.toString() !== params.toString()) {
    const newUrl = params.toString() ? `/docs?${params.toString()}` : "/docs";
    router.replace(newUrl, { scroll: false });
  }
}, [selectedType, selectedStatus, searchQuery, selectedTags, router, searchParams, loading, manifest]);

